import {createTradingDesk} from './trading-desk.js';
import {liveMarkets,liveNow,liveState,updateLiveFreshness} from './live-view.js';
import {DEFAULT_RISK,levels,fillBook,pairQuote,crossQuotes,analyze,backtest,newWallet,exposure,riskCheck,openPaper,closePaper,makerQuote} from './engine.js';
const $=s=>document.querySelector(s), KEY='fainance.paper.v2';
let lang=localStorage.getItem('fainance.language')||'ar';
const t=(ar,en)=>lang==='ar'?ar:en,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=2)=>Number.isFinite(Number(v))&&v!==null?Number(v).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}):'—';
const money=(v,d=2)=>v===null||v===undefined?'—':`$${n(v,d)}`,pct=v=>v==null?'—':`${v>0?'+':''}${n(v)}%`,sign=v=>v>=0?'positive':'negative';
const time=v=>v?new Date(v).toLocaleTimeString(lang==='ar'?'ar-KW':'en-GB',{timeZone:'Asia/Kuwait',hour:'2-digit',minute:'2-digit',second:'2-digit'}):'—';
const date=v=>new Date(v).toLocaleDateString(lang==='ar'?'ar-KW':'en-GB',{timeZone:'Asia/Kuwait',day:'numeric',month:'short'});
let wallet;try{wallet=JSON.parse(localStorage.getItem(KEY));if(wallet?.version!==2||!Array.isArray(wallet.positions))wallet=null;}catch{}wallet||=newWallet();wallet.auto=false;wallet.risk={...DEFAULT_RISK,...wallet.risk};
const S={page:'stp',marketData:null,marketClock:null,marketLoading:true,marketRefreshing:false,marketFetchFailed:false,snapshot:null,candles:[],interval:'5m',loading:true,error:false,frame:'all',qty:100,positiveOnly:false,scanner:'poly',strategy:'trend',result:null,model:null,auto:false,busy:false,mobile:false,refreshing:false};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',scan:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M3 12h18"/><circle cx="12" cy="12" r="4"/>',chart:'<path d="M3 3v18h18M6 15l5-5 4 3 6-8"/>',wallet:'<path d="M20 8V5H5a2 2 0 0 0 0 4h16v12H5a2 2 0 0 1-2-2V7"/><path d="M21 12h-6v5h6"/><path d="M17 14.5h.1"/>',shield:'<path d="M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="M8 12l3 3 5-6"/>',spark:'<path d="M12 3l2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3zM20 2v4m-2-2h4"/>',plug:'<path d="M8 3v5m8-5v5M5 8h14v4a7 7 0 0 1-7 7v3M7 8v4a5 5 0 0 0 10 0V8"/>',refresh:'<path d="M20 11a8 8 0 0 0-14-5L3 9m0-6v6h6M4 13a8 8 0 0 0 14 5l3-3m0 6v-6h-6"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="3"/>',arrow:'<path d="M6 18L18 6M6 6h12v12"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',check:'<path d="M5 12l4 4L19 6"/>',code:'<path d="M8 5l-6 7 6 7m8-14l6 7-6 7M14 3l-4 18"/>',book:'<path d="M12 5c-4-3-9-2-9-2v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2v16"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',download:'<path d="M12 3v12m-5-5l5 5 5-5M4 15v6h16v-6"/>',play:'<path d="M7 4l14 8-14 8z"/>',layers:'<path d="M12 3L2 8l10 5 10-5zM2 12l10 5 10-5M2 16l10 5 10-5"/>',activity:'<path d="M2 12h5l3-8 4 16 3-8h5"/>'})[name]||''}</svg>`;
const btcIcon=()=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M7 6h7a3 3 0 0 1 0 6H7m0 0h8a3 3 0 0 1 0 6H7M9 6v12M11 3v3m4-3v3m-4 12v3m4-3v3"/></svg>';
const labels=()=>({stp:t('مسار سعد للتداول','Saad Trading Path'),signals:t('اقتناص الفرص','Trade opportunities'),execution:t('التنفيذ والمخاطر','Execution & risk'),markets:t('السوق الآن','Live markets'),dashboard:t('نظرة عامة','Overview'),opportunities:t('رادار الفرص','Opportunity radar'),lab:t('مختبر الاستراتيجيات','Strategy lab'),portfolio:t('المحفظة التجريبية','Paper portfolio'),intelligence:t('التحليل الذكي','Intelligence'),risk:t('مخاطر محفظة Polymarket','Polymarket portfolio risk'),connectors:t('المصادر والربط','Data & connections')});
const reasons={liveQuote:['قراءة سوق','Market quote'],noEdge:['العائد أقل من الحد المحدد','Edge is below your threshold'],invalidPair:['الطرفان غير متطابقين','Invalid complete set'],expired:['انتهى السوق أو اقترب الإغلاق','Expired or closing'],stale:['البيانات قديمة','Stale quotes'],feeUnknown:['الرسوم غير مؤكدة','Fee schedule unavailable'],minSize:['الكمية أقل من الحد الأدنى','Below minimum size'],depth:['سيولة غير كافية','Insufficient depth'],halted:['إيقاف الطوارئ مفعّل','Emergency stop is active'],invalidAmount:['أدخل كمية صحيحة','Enter a valid amount'],tradeLimit:['تجاوز حد الصفقة','Per-trade limit exceeded'],balance:['الرصيد لا يكفي','Insufficient paper balance'],exposureLimit:['تجاوز حد الانكشاف','Exposure limit exceeded'],positionLimit:['تجاوز عدد المراكز','Position limit exceeded'],dailyLoss:['بلغت حد الخسارة اليومية','Daily loss limit reached'],sourceUnavailable:['المصدر غير متاح حاليًا','Source currently unavailable'],insufficientHistory:['لا توجد شموع كافية للاختبار','Insufficient candle history'],duplicate:['يوجد مركز لهذا السوق','This market already has a position']};
const reason=k=>reasons[k]?t(...reasons[k]):t('تعذر إكمال العملية. حاول التحديث.','Unable to complete. Try refreshing.');
const log=(key,detail='')=>{wallet.events.unshift({key,detail,at:Date.now()});wallet.events=wallet.events.slice(0,1000);};
function save(){try{localStorage.setItem(KEY,JSON.stringify({...wallet,auto:false}));}catch{toast(t('تعذر حفظ المحفظة على الجهاز. صدّر نسخة احتياطية.','Local save failed. Export a backup.'));S.auto=false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
const btn=(text,action,cls='',extra='')=>`<button class="button ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const status=(ok,yes=t('متصل','Connected'),no=t('غير متاح','Unavailable'))=>`<span class="status"><i class="dot ${ok?'':'off'}"></i>${ok?yes:no}</span>`;
const empty=(title,body,i='scan')=>`<div class="empty">${icon(i)}<strong>${title}</strong>${body}</div>`;
const notice=(msg,warning=false)=>`<div class="notice ${warning?'warning':''}">${icon('info')}<span>${msg}</span></div>`;
const stat=(label,value,foot,ico='activity',color='')=>`<div class="stat"><div class="label">${label}${icon(ico)}</div><div class="stat-value ${color}">${value}</div><div class="stat-foot">${foot}</div></div>`;
function freshBook(){const all=S.snapshot?.exchanges.filter(x=>x.ok&&Date.now()-x.asOf<20000&&x.asOf<Date.now()+3000)||[];return all.find(x=>x.id===S.historySource)||all[0]||null;}
const book=()=>freshBook()||S.snapshot?.exchanges.find(x=>x.ok)||null;
function mark(p){if(p.kind==='pair')return {value:p.cost,pnl:0,available:true,held:true};const b=freshBook();const q=b?fillBook(b.bids,p.qty,'sell',wallet.risk.slippageBps,wallet.risk.spotFeeBps):null;return {value:q?.total??p.cost,pnl:q?q.total-p.cost:null,available:!!q};}
function totals(){const mv=wallet.positions.reduce((a,p)=>a+mark(p).value,0),realized=wallet.trades.reduce((s,p)=>s+p.pnl,0);return {equity:wallet.cash+mv,realized,pnl:wallet.cash+mv-wallet.initial,exposure:exposure(wallet),missing:wallet.positions.some(p=>!mark(p).available)};}
function candidates(){return (S.snapshot?.markets||[]).map(m=>({m,q:pairQuote(m,S.qty,wallet.risk.slippageBps)})).sort((a,b)=>(b.q.edgePct??-999)-(a.q.edgePct??-999));}
function chart(c,mode='candles'){
  if(!c?.length)return `<div class="chart-empty">${icon('chart')}<span>${S.loading?t('جارٍ جلب بيانات السوق…','Fetching market data…'):t('بيانات الرسم غير متاحة','Chart data unavailable')}</span></div>`;
  const narrow=window.innerWidth<760;const data=mode==='candles'?c.slice(narrow?-36:-65):c,W=narrow?Math.max(280,window.innerWidth-58):800,H=255,pad=narrow?54:65,top=14,bottom=28,min0=Math.min(...data.map(x=>mode==='candles'?x.low:x.value)),max0=Math.max(...data.map(x=>mode==='candles'?x.high:x.value)),range=Math.max(max0-min0,max0*.0005),min=min0-range*.08,max=max0+range*.08,y=v=>top+(max-v)/(max-min)*(H-top-bottom),x=i=>10+i*(W-pad-10)/Math.max(1,data.length-1);
  const lines=Array.from({length:5},(_,i)=>{const v=min+(max-min)*i/4;return `<line x1="5" x2="${W-pad+8}" y1="${y(v)}" y2="${y(v)}" stroke="#27383e" stroke-dasharray="3 6"/><text x="${W-pad+18}" y="${y(v)+4}">${n(v,v>100?0:2)}</text>`}).join('');
  let graph='';if(mode==='candles')graph=data.map((v,i)=>{const color=v.close>=v.open?'#97cb76':'#da8483',bw=Math.max(2,(W-pad)/data.length*.55);return `<line x1="${x(i)}" x2="${x(i)}" y1="${y(v.high)}" y2="${y(v.low)}" stroke="${color}"/><rect x="${x(i)-bw/2}" y="${y(Math.max(v.open,v.close))}" width="${bw}" height="${Math.max(1.3,Math.abs(y(v.open)-y(v.close)))}" rx=".5" fill="${color}"/>`}).join('');
  else{const d=data.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v.value)}`).join(' ');graph=`<path d="${d} L${x(data.length-1)},${H-bottom} L10,${H-bottom}Z" fill="url(#fade)"/><path d="${d}" fill="none" stroke="#c6f372" stroke-width="2"/>`;}
  const times=[0,Math.floor(data.length/3),Math.floor(2*data.length/3),data.length-1].map(i=>`<text x="${x(i)}" y="${H-6}" text-anchor="${i===0?'start':i===data.length-1?'end':'middle'}">${new Date(data[i].time).toLocaleTimeString('en-GB',{timeZone:'Asia/Kuwait',hour:'2-digit',minute:'2-digit'})}</text>`).join('');
  return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="${t('رسم أسعار الشموع المغلقة','Closed-candle price chart')}"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#c6f372" stop-opacity=".16"/><stop offset="100%" stop-color="#c6f372" stop-opacity="0"/></linearGradient></defs>${lines}${graph}${times}</svg>`;
}
function pageTitle(title,subtitle,action=''){return `<div class="page-title"><div><div class="eyebrow">FAINANCE / ${S.page.toUpperCase()}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function chartPanel(){const b=book(),a=S.model,delta=S.candles.length>1?(S.candles.at(-1).close/S.candles.at(-2).close-1)*100:null;return `<section class="panel"><div class="panel-head"><div><h2>${t('نبض السوق','Market pulse')} <span class="pill grey num">BTC / USDT</span></h2><div class="sub">${S.historySource||'—'} · ${t('شموع مكتملة','Closed candles')}</div></div><div class="segmented">${['1m','5m','15m','1h'].map(x=>`<button class="${S.interval===x?'active':''}" data-interval="${x}">${x}</button>`).join('')}</div></div><div class="price-line"><div class="coin">${btcIcon()}</div><div class="ticker"><strong class="num">${b?money(b.price):'—'}</strong><span class="num ${sign(delta)}">${pct(delta)}</span><small class="muted">${t('آخر شمعة','Last candle')}</small></div></div><div class="chart-wrap">${chart(S.candles)}</div><div class="chart-bottom"><span>RSI <b class="num ${a?.rsi>70?'amber':'positive'}">${a?n(a.rsi,1):'—'}</b></span><span>EMA 9 <b class="num">${a?n(a.fast):'—'}</b></span><span>EMA 21 <b class="num">${a?n(a.slow):'—'}</b></span><span>${t('عمق الشراء','Buy depth')} <b class="num">${b?n(b.bids.reduce((s,x)=>s+x.size,0),3):'—'} BTC</b></span></div></section>`;}
function insightText(){const a=S.model,count=candidates().filter(x=>x.q.ok&&x.q.edgePct>=wallet.risk.minEdge).length;if(!S.snapshot)return t('أنتظر وصول بيانات السوق لتكوين قراءة موثوقة.','Waiting for market data to build an evidence-based reading.');if(count)return t(`رصدت ${count} فرص تستوفي حد العائد النموذجي. افحص حداثة الأسعار وسيولة الطرفين قبل المحاكاة.`,`${count} candidates pass your modeled edge threshold. Check quote freshness and both order books before simulating.`);if(!a)return t('لا توجد بيانات كافية للتحليل. انتظار البيانات أفضل من اختلاق إشارة.','Insufficient data for analysis. Waiting for verified inputs.');return a.trend==='up'?t('المتوسط القصير أعلى من الطويل. الزخم صاعد، لكن تكلفة التحوط قد تمحو فرق التسعير.','The fast average is above the slow average. Momentum is positive; hedging costs can still erase a pricing edge.'):t('المتوسط القصير أقل من الطويل. الزخم ضعيف؛ راقب الانكشاف ولا تعتبر شراء الطرفين ضمانًا للربح.','The fast average is below the slow average. Momentum is weak; monitor exposure and the full cost of both legs.');}
function dashboard(){const v=totals(),cs=candidates(),count=cs.filter(x=>x.q.ok&&x.q.edgePct>=wallet.risk.minEdge).length;return `${pageTitle(t('كل الأسواق. رؤية واحدة.','Every market. One clear view.'),t('راقب الفرص، اختبر الفكرة، وتحكّم بالمخاطر.','Spot opportunities, test your thesis, and stay in control.'),btn(icon('refresh')+t('تحديث الأسواق','Refresh markets'),'refresh','',S.refreshing?'disabled':''))}<div class="stats">${stat(t('قيمة المحفظة التجريبية','Paper account equity'),money(v.equity),t('رصيد افتراضي · محفوظ على هذا الجهاز','Virtual funds · stored on this device'),'wallet')}${stat(t('صافي النتيجة التجريبية','Net paper P&L'),money(v.pnl),`${pct(v.pnl/wallet.initial*100)} · ${t('بعد تكاليف النموذج','After modeled costs')}`,'chart',sign(v.pnl))}${stat(t('فرص تستوفي الحد','Candidates above threshold'),S.snapshot?String(count).padStart(2,'0'):'—',t('عائد نموذجي، التنفيذ غير مضمون','Modeled edge; execution is uncertain'),'scan')}${stat(t('المبلغ المستثمر','Deployed paper capital'),money(v.exposure),`${wallet.positions.length} ${t('مراكز مفتوحة','open positions')} · ${n(v.exposure/wallet.risk.maxExposure*100,0)}% ${t('من الحد','of limit')}`,'shield')}</div><div class="grid dashboard-grid">${chartPanel()}<div class="stack"><section class="panel insight"><div class="insight-top">${icon('spark')}<h2>${t('قراءة ذكية للسوق','Market intelligence')}</h2><span class="spacer"></span><span class="pill grey">${t('تحليل','Analysis')}</span></div><p>${insightText()}</p><div class="insight-meta"><span>${t('مؤشرات + نموذج تعلّم آلي','Indicators + machine learning')}</span><button class="inline-link" data-page="intelligence">${t('التفاصيل','Details')}</button></div></section><section class="panel"><div class="panel-head"><h2>${icon('shield')}${t('حالة الحماية','Risk guard')}</h2>${status(!wallet.halted,t('مفعّلة','Active'),t('متوقف','Halted'))}</div><div class="panel-body"><div class="metric-row"><span>${t('الحد لكل صفقة','Per-trade limit')}</span><b class="num">${money(wallet.risk.maxTrade,0)}</b></div><div class="metric-row"><span>${t('حد الخسارة اليومية','Daily loss limit')}</span><b class="num">${money(wallet.risk.dailyLoss,0)}</b></div><div class="metric-row"><span>${t('تغطية المراكز المزدوجة','Paired-position coverage')}</span><span class="num">${wallet.positions.some(p=>p.kind==='pair')?'100%':'—'}</span></div><div class="bar"><i style="width:${Math.min(100,v.exposure/wallet.risk.maxExposure*100)}%"></i></div><small class="muted">${t('استخدام حد الانكشاف','Exposure limit utilization')}</small></div></section></div></div><section class="panel below"><div class="panel-head"><div><h2>${icon('scan')}${t('رادار Polymarket','Polymarket radar')}</h2><div class="sub">${t('شراء صعود + هبوط لنفس السوق • تقدير بعد الرسوم والانزلاق','Buy UP + DOWN in the same market • after fees and slippage')}</div></div><button class="inline-link" data-page="opportunities">${t('عرض كل الفرص','View all opportunities')}</button></div>${marketTable(cs.slice(0,4))}</section>`;}
function marketTable(items){if(!items.length)return empty(S.loading?t('جارٍ مسح الأسواق','Scanning markets'):t('لا توجد أسواق متاحة الآن','No markets available'),t('ستظهر دفاتر الأوامر عند استجابة المصدر. لا تُستخدم أسعار بديلة.','Order books will appear when the source responds. No substitute prices are used.'));return `<div class="table-scroll"><table><thead><tr><th>${t('السوق / الاستحقاق','Market / expiry')}</th><th>${t('صعود','UP')}</th><th>${t('هبوط','DOWN')}</th><th>${t('تكلفة الزوج','Pair cost')}</th><th>${t('العائد النموذجي','Modeled edge')}</th><th>${t('القرار','Decision')}</th><th></th></tr></thead><tbody>${items.map(({m,q})=>{const remaining=Math.max(0,Math.ceil((Date.parse(m.endDate)-Date.now())/60000));return `<tr><td><div class="market-cell"><span class="coin">${btcIcon()}</span><div><strong>Bitcoin <span class="num">${esc(m.frame)}</span></strong><small>${t('ينتهي خلال','Expires in')} <span class="num">${remaining}</span> ${t('دقيقة','min')} · ${new Date(m.endDate).toLocaleTimeString('en-GB',{timeZone:'Asia/Kuwait',hour:'2-digit',minute:'2-digit'})}</small></div></div></td><td class="num">${m.up.asks.length?n(m.up.asks[0].price*100,1)+'¢':'—'}</td><td><span class="num">${m.down.asks.length?n(m.down.asks[0].price*100,1)+'¢':'—'}</span></td><td><span class="num">${q.ok?money(q.total/q.qty,4):'—'}</span></td><td><span class="num ${q.ok?sign(q.edgePct):'muted'}">${q.ok?pct(q.edgePct):'—'}</span></td><td><span class="pill ${!q.ok?'amber':q.edgePct>=wallet.risk.minEdge?'':'grey'}">${!q.ok?reason(q.reason):q.edgePct>=wallet.risk.minEdge?t('قابلة للفحص','Candidate'):t('انتظار','Wait')}</span></td><td>${btn(t('فحص','Inspect'),'inspect','compact',`data-id="${esc(m.id)}"`)}</td></tr>`}).join('')}</tbody></table></div>`;}
function opportunities(){const cs=candidates().filter(x=>(S.frame==='all'||x.m.frame===S.frame)&&(!S.positiveOnly||x.q.ok&&x.q.edgePct>=wallet.risk.minEdge));return `${pageTitle(t('رادار الفرص','Opportunity radar'),t('السعر الأفضل لا يكفي. احسب تكلفة التنفيذ كاملة.','A better price is only the beginning. Account for execution costs.'),btn(icon('refresh')+t('إعادة المسح','Scan again'),'refresh'))}<div class="tabs"><button data-scanner="poly" class="${S.scanner==='poly'?'active':''}">Polymarket</button><button data-scanner="cross" class="${S.scanner==='cross'?'active':''}">${t('مقارنة المنصات','Exchange comparison')}</button><button data-scanner="maker" class="${S.scanner==='maker'?'active':''}">${t('صناعة السوق والتحوط','Market making & hedging')}</button></div>${S.scanner==='poly'?`${notice(t('الصافي تقديري بعد رسوم السوق والانزلاق المفترض. شراء الطرفين ليس تنفيذًا ذريًا؛ تكاليف التسوية والشبكة غير محسوبة.','Net edge includes market fees and assumed slippage. The two orders are not atomic; settlement and network costs are excluded.'))}<div class="toolbar"><div class="filters" style="margin:0"><div class="segmented">${['all','5m','15m','1h'].map(f=>`<button data-frame="${f}" class="${S.frame===f?'active':''}">${f==='all'?t('الكل','All'):f}</button>`).join('')}</div><label for="scanQty">${t('عدد الأزواج','Pair shares')}</label><input id="scanQty" type="number" min="5" max="10000" value="${S.qty}"><label class="check-label"><input type="checkbox" id="positiveOnly" ${S.positiveOnly?'checked':''}>${t('فوق حد العائد فقط','Above threshold only')}</label></div><span class="muted small">${t('الحد الأدنى للعائد','Minimum edge')}: <span class="num">${n(wallet.risk.minEdge)}%</span></span></div><section class="panel">${marketTable(cs)}</section><section class="panel below"><div class="panel-head"><h2>${t('البوت التجريبي','Paper trading bot')}</h2><span class="pill ${S.auto?'':'grey'}">${S.auto?t('يعمل في هذه الصفحة','Running in this tab'):t('متوقف','Stopped')}</span></div><div class="panel-body"><p class="muted">${t('يفحص كل 10 ثوانٍ وينشئ أزواجًا افتراضية فقط عند تجاوز صافي العائد والحدود المحددة. يعمل أثناء فتح الصفحة.','Scans every 10 seconds and creates virtual pairs only when modeled edge and risk checks pass. Runs while this page stays open.')}</p><div class="form-actions">${btn((S.auto?icon('stop'):icon('play'))+(S.auto?t('إيقاف البوت','Stop bot'):t('تشغيل البوت التجريبي','Start paper bot')),'auto','primary')}</div></div></section>`:S.scanner==='cross'?crossPanel():makerPanel()}`;}
function crossPanel(){const rows=crossQuotes(S.snapshot?.exchanges||[],.001,wallet.risk.spotFeeBps,wallet.risk.slippageBps);return `${notice(t('مقارنة BTC/USDT لكمية 0.001 BTC. الرسوم افتراض قابل للتعديل وليست شريحة حسابك. يلزم تمويل مسبق في المنصتين؛ لا تشمل التحويل أو إعادة الموازنة.','BTC/USDT comparison for 0.001 BTC. Fees are editable assumptions, not your account tier. Requires prefunded inventory on both venues; transfers and rebalancing are excluded.'),true)}<div class="cols3">${(S.snapshot?.exchanges||['Binance','OKX','Bybit'].map(id=>({id,ok:false}))).map(e=>`<section class="panel source-card"><div class="source-top"><h2>${e.id}</h2>${status(e.ok&&Date.now()-e.asOf<20000)}</div><div class="stat-value">${e.ok?money(e.price):'—'}</div><div class="metric-row"><span>${t('أفضل شراء','Best bid')}</span><span class="num">${e.ok?n(e.bids[0].price):'—'}</span></div><div class="metric-row"><span>${t('أفضل بيع','Best ask')}</span><span class="num">${e.ok?n(e.asks[0].price):'—'}</span></div><small class="muted">${e.ok?time(e.asOf):reason('sourceUnavailable')}</small></section>`).join('')}</div><section class="panel below"><div class="panel-head"><h2>${t('فروق الأسعار بعد التكاليف','Spreads after modeled costs')}</h2><span class="pill grey">${t('مراقبة فقط','Monitor only')}</span></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>${t('الشراء من','Buy at')}</th><th>${t('البيع في','Sell at')}</th><th>${t('الرسوم','Fees')}</th><th>${t('صافي الفرق','Net spread')}</th><th>${t('العائد','Return')}</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.buy}</td><td>${r.sell}</td><td><span class="num">${money(r.fees,4)}</span></td><td><span class="num ${sign(r.net)}">${money(r.net,4)}</span></td><td><span class="num ${sign(r.edgePct)}">${pct(r.edgePct)}</span></td></tr>`).join('')}</tbody></table></div>`:empty(t('نحتاج مصدرين حديثين','Two fresh sources required'),t('لا يمكن حساب فرق موثوق عند تعطل أحد الطرفين.','A reliable spread requires fresh quotes from both venues.'))}</section>`;}
function makerPanel(){return `${notice(t('مخطط أسعار لصانع السوق وحاسبة التحوط. الأوامر المقترحة لا تعني أنها ستُنفّذ؛ لا تُسجّل أرباح من مجرد ملامسة السعر.','Market-maker quote planner and hedge calculator. Proposed orders are not fills; a touched quote does not create paper profits.'))}<div class="cols2"><section class="panel"><div class="panel-head"><h2>${t('مخطط عروض الأسعار','Quote planner')}</h2></div><form id="makerForm" class="panel-body"><div class="form-grid"><div class="field"><label>${t('فرق التسعير (نقطة أساس)','Quoted spread (bps)')}</label><input name="spread" type="number" value="20" min="1" max="500" required></div><div class="field"><label>${t('ميل المخزون (%)','Inventory imbalance (%)')}</label><input name="inventory" type="number" value="0" min="-100" max="100" required></div></div><div class="form-actions"><button class="button primary">${t('احسب الأسعار','Calculate quotes')}</button></div><div id="makerResult"></div></form></section><section class="panel"><div class="panel-head"><h2>${t('ما مقدار المركز المحوّط؟','How much is hedged?')}</h2></div><form id="hedgeForm" class="panel-body"><div class="form-grid"><div class="field"><label>${t('أسهم الصعود','UP shares')}</label><input name="up" type="number" value="100" min="0" max="1000000" required></div><div class="field"><label>${t('أسهم الهبوط','DOWN shares')}</label><input name="down" type="number" value="70" min="0" max="1000000" required></div></div><div class="form-actions"><button class="button primary">${t('احسب التغطية','Calculate coverage')}</button></div><div id="hedgeResult"></div></form></section></div>`;}
function lab(){const choices=[['trend','chart',t('تتبّع الاتجاه','Trend following'),t('تقاطع EMA 9 و EMA 21','EMA 9 / EMA 21 crossover')],['mean','activity',t('العودة للمتوسط','Mean reversion'),t('دخول RSI < 30 وخروج RSI > 60','Enter RSI < 30; exit RSI > 60')],['ml','spark',t('نموذج تعلّم آلي','Machine learning'),t('انحدار لوجستي · اختبار خارج التدريب','Logistic regression · holdout test')]];return `${pageTitle(t('اختبر قبل أن تتداول','Test before you trade'),t('اختبار تاريخي على شموع البيتكوين الحقيقية، مع احتساب التكاليف.','Backtest real Bitcoin candles with fees and slippage.'))}<div class="option-cards">${choices.map(([id,ico,title,desc])=>`<button class="option-card ${S.strategy===id?'active':''}" data-strategy="${id}">${icon(ico)}<strong>${title}</strong><span>${desc}</span></button>`).join('')}</div><section class="panel"><div class="panel-head"><h2>${t('إعداد تجربة','Configure experiment')}</h2><span class="pill grey">${S.candles.length} ${t('شموع مغلقة','closed candles')} · ${S.interval}</span></div><form id="backtestForm" class="panel-body"><div class="form-grid"><div class="field"><label for="backCapital">${t('رأس المال التجريبي','Virtual starting capital')}</label><input id="backCapital" name="capital" type="number" value="10000" min="100" max="10000000" required></div><div class="field"><label>${t('فاصل الشموع','Candle interval')}</label><div class="segmented">${['1m','5m','15m','1h'].map(x=>`<button type="button" class="${S.interval===x?'active':''}" data-interval="${x}">${x}</button>`).join('')}</div></div><div class="field"><label for="backFee">${t('رسوم كل طرف (نقطة أساس)','Fee per side (bps)')}</label><input id="backFee" name="feeBps" type="number" value="${wallet.risk.spotFeeBps}" min="0" max="200" required></div><div class="field"><label for="backSlip">${t('انزلاق كل طرف (نقطة أساس)','Slippage per side (bps)')}</label><input id="backSlip" name="slippageBps" type="number" value="${wallet.risk.slippageBps}" min="0" max="500" required></div></div><p class="muted small mt">${t('شراء فقط، 20% من السيولة لكل دخول. الإشارة عند إغلاق الشمعة والتنفيذ عند افتتاح التالية. النموذج الآلي يتدرّب على أول 65% ويُختبر على الباقي. لا يُحاكي هذا الاختبار طابور أوامر Polymarket.','Long only, 20% of available cash per entry. Signals use the closed candle; fills use the next open. ML trains on the first 65% and is tested on the remainder. This does not backtest Polymarket order queues.')}</p><div class="form-actions"><button class="button primary" ${S.candles.length<60?'disabled':''}>${icon('play')}${t('تشغيل الاختبار','Run backtest')}</button></div></form></section>${S.result?backtestResult():notice(t('النتائج التاريخية لا تتنبأ بالأرباح المستقبلية. تتغير النتائج مع الفترة والرسوم المختارة.','Historical results do not predict future profits. Results depend on the chosen window and costs.'))}`;}
function backtestResult(){const r=S.result;return `<div class="stats below">${stat(t('صافي النتيجة','Net result'),money(r.pnl),pct(r.returnPct),'chart',sign(r.pnl))}${stat(t('أقصى تراجع','Maximum drawdown'),n(r.drawdown)+'%',t('من ذروة رأس المال','From peak equity'),'shield')}${stat(t('الصفقات المكتملة','Closed trades'),String(r.trades.length),`${t('نسبة الربح','Win rate')}: ${r.winRate===null?'—':n(r.winRate,1)+'%'}`,'layers')}${stat(t('مدة الاختبار','Test window'),n((r.end-r.start)/3600000,1)+'h',date(r.start)+' — '+date(r.end),'clock')}</div><section class="panel"><div class="panel-head"><h2>${t('منحنى رأس المال','Equity curve')}</h2>${btn(icon('download')+t('تصدير النتيجة','Export results'),'exportBacktest','compact')}</div><div class="chart-wrap">${chart(r.curve,'line')}</div>${r.model?`<div class="panel-body muted small">${t('دقة الاختبار','Holdout accuracy')}: <span class="num">${n(r.model.accuracy*100,1)}%</span> · ${t('خط الأساس','Majority baseline')}: <span class="num">${n(r.model.baseline*100,1)}%</span> · ${r.model.testCount} ${t('عينة اختبار','test samples')}</div>`:''}</section>`;}
function portfolio(){const v=totals();return `${pageTitle(t('محفظتك التجريبية','Your paper portfolio'),t('أموال افتراضية، أسعار سوق حقيقية، ونتائج قابلة للمراجعة.','Virtual capital, real market quotes, and auditable results.'),btn(icon('download')+t('تصدير السجل','Export ledger'),'exportWallet'))}${notice(t('هذه المحفظة محفوظة في متصفحك على هذا الجهاز فقط، ولا تمثل حسابًا ماليًا أو رصيدًا حقيقيًا. احتفظ بنسخة مصدّرة قبل مسح المتصفح.','This wallet is stored only in this browser on this device. It is not a financial account or real balance. Export a backup before clearing browser data.'))}<div class="stats">${stat(t('السيولة المتاحة','Available cash'),money(wallet.cash),t('دولار افتراضي','Virtual dollars'),'wallet')}${stat(t('نتيجة محققة','Realized P&L'),money(v.realized),`${wallet.trades.length} ${t('صفقات مكتملة','closed trades')}`,'chart',sign(v.realized))}${stat(t('انكشاف مفتوح','Open exposure'),money(v.exposure),t('بسعر التكلفة','At entry cost'),'layers')}${stat(t('قيمة الحساب','Account equity'),money(v.equity),v.missing?t('تقييم جزئي: أسعار غير متاحة','Partial valuation: quotes unavailable'):t('الأزواج بالتكلفة حتى الاستحقاق','Pairs held at cost until maturity'),'shield')}</div><div class="cols2"><section class="panel"><div class="panel-head"><h2>${t('شراء بيتكوين تجريبي','Paper Bitcoin buy')}</h2><span class="pill grey">BTC / USDT</span></div><form id="spotForm" class="panel-body"><div class="field"><label for="spotBudget">${t('ميزانية الصفقة شاملة التكاليف','Budget including modeled costs')}</label><input name="budget" id="spotBudget" type="number" value="100" min="10" max="100000" required></div><div class="metric-row"><span>${t('وقف الخسارة / جني الربح','Stop loss / take profit')}</span><span class="num">${wallet.risk.stopLossPct}% / ${wallet.risk.takeProfitPct}%</span></div><small class="muted">${t('يُقيّم الوقف عند التحديث كل 10 ثوانٍ أثناء فتح الصفحة؛ قد يُنفّذ بعد تجاوز المستوى.','Stops are evaluated on 10-second refreshes while this tab is open; gaps may produce worse fills.')}</small><div class="form-actions"><button class="button primary" ${wallet.halted||!freshBook()?'disabled':''}>${t('شراء تجريبي','Paper buy')}</button></div></form></section><section class="panel"><div class="panel-head"><h2>${t('توزيع رأس المال','Capital allocation')}</h2></div><div class="panel-body"><div class="metric-row"><span>${t('سيولة افتراضية','Paper cash')}</span><span class="num">${money(wallet.cash)}</span></div><div class="metric-row"><span>${t('أزواج محوّطة بالكامل','Complete paired positions')}</span><span class="num">${money(wallet.positions.filter(p=>p.kind==='pair').reduce((s,p)=>s+p.cost,0))}</span></div><div class="metric-row"><span>${t('بيتكوين مكشوف للاتجاه','Directional Bitcoin')}</span><span class="num">${money(wallet.positions.filter(p=>p.kind==='spot').reduce((s,p)=>s+p.cost,0))}</span></div><div class="allocation mt"><i style="width:${Math.max(0,Math.min(100,wallet.cash/Math.max(v.equity,1)*100))}%"></i><i style="flex:1"></i></div></div></section></div><section class="panel below"><div class="panel-head"><h2>${t('المراكز المفتوحة','Open positions')}</h2><span class="pill grey">${wallet.positions.length}</span></div>${wallet.positions.length?`<div class="table-scroll"><table><thead><tr><th>${t('المركز','Position')}</th><th>${t('الكمية','Quantity')}</th><th>${t('التكلفة','Cost')}</th><th>${t('التقييم / العائد','Valuation / P&L')}</th><th>${t('الخروج','Exit')}</th></tr></thead><tbody>${wallet.positions.map(p=>{const m=mark(p);return `<tr><td>${p.kind==='pair'?`Polymarket · ${esc(p.frame)}`:'BTC / USDT'}<small class="muted" style="display:block">${p.kind==='pair'?t('زوج مكتمل · نموذج تسوية','Complete set · modeled settlement'):t('شراء اتجاهي','Directional long')}</small></td><td><span class="num">${n(p.qty,p.kind==='pair'?2:6)}</span></td><td><span class="num">${money(p.cost)}</span></td><td><span class="num ${sign(m.pnl)}">${p.kind==='pair'?money(p.payout)+' '+t('عند الاستحقاق','at maturity'):m.available?money(m.pnl):'—'}</span></td><td>${p.kind==='pair'?`<small class="muted">${time(p.endAt)}</small>`:btn(t('إغلاق','Close'),'closeSpot','compact',`data-id="${esc(p.id)}" ${!m.available?'disabled':''}`)}</td></tr>`}).join('')}</tbody></table></div>`:empty(t('مساحة لبداية مدروسة','Ready for your first position'),t('ابدأ بشراء تجريبي أو افحص زوجًا من رادار الفرص.','Try a paper buy or inspect a pair in the opportunity radar.'),'wallet')}</section><section class="panel below"><div class="panel-head"><h2>${t('سجل الصفقات','Trade history')}</h2><span class="muted small">${t('آخر 30 صفقة','Last 30 trades')}</span></div>${wallet.trades.length?`<div class="table-scroll"><table><thead><tr><th>${t('الوقت','Time')}</th><th>${t('المركز','Position')}</th><th>${t('التكلفة','Cost')}</th><th>${t('المتحصل','Proceeds')}</th><th>${t('الصافي','Net')}</th><th>${t('سبب الإغلاق','Exit reason')}</th></tr></thead><tbody>${wallet.trades.slice(0,30).map(p=>`<tr><td>${date(p.closedAt)} ${time(p.closedAt)}</td><td>${p.kind==='pair'?'Polymarket':'BTC/USDT'}</td><td class="num">${money(p.cost)}</td><td><span class="num">${money(p.proceeds)}</span></td><td><span class="num ${sign(p.pnl)}">${money(p.pnl)}</span></td><td>${eventLabel(p.reason)}</td></tr>`).join('')}</tbody></table></div>`:empty(t('لا صفقات مكتملة بعد','No completed trades yet'),t('ستظهر الأرباح والخسائر هنا بعد إغلاق المراكز.','P&L appears here after positions close.'),'book')}</section>`;}
function intelligence(){const a=S.model,m=a?.model;return `${pageTitle(t('ذكاء يمكن فحصه','Intelligence you can inspect'),t('كل قراءة مرتبطة ببياناتها، وكل قرار له سبب.','Every reading has evidence. Every decision has a reason.'))}<div class="cols2"><section class="panel insight"><div class="insight-top">${icon('spark')}<h2>${t('ملخص السوق','Market briefing')}</h2></div><p>${insightText()}</p><ul class="feature-list"><li>${icon('check')}<span>${t('اتجاه EMA','EMA trend')}: ${!a?'—':a.trend==='up'?t('صاعد','Upward'):t('هابط','Downward')}</span></li><li>${icon('check')}<span>RSI 14: <span class="num">${a?n(a.rsi,1):'—'}</span></span></li><li>${icon('check')}<span>${t('التكاليف والانكشاف يُفحصان قبل أي صفقة تجريبية.','Costs and exposure are checked before every paper entry.')}</span></li></ul><div class="insight-meta">${t('تحليل محلي قابل للتفسير، دون اتصال بمساعد لغوي.','Local, explainable analytics. No language-model service is connected.')}</div></section><section class="panel"><div class="panel-head"><h2>${t('نموذج اتجاه الشمعة التالية','Next-candle direction model')}</h2><span class="pill amber">${t('تجريبي','Experimental')}</span></div><div class="panel-body">${m?`<div class="metric-row"><span>${t('احتمال صعود النموذج','Model upward probability')}</span><span class="num green">${n(m.probability*100,1)}%</span></div><div class="metric-row"><span>${t('دقة الاختبار خارج التدريب','Holdout accuracy')}</span><span class="num">${n(m.accuracy*100,1)}%</span></div><div class="metric-row"><span>${t('خط أساس الفئة الأكثر شيوعًا','Majority-class baseline')}</span><span class="num">${n(m.baseline*100,1)}%</span></div><div class="metric-row"><span>${t('تدريب / اختبار','Train / test samples')}</span><span class="num">${m.trainCount} / ${m.testCount}</span></div>`:empty(t('بيانات غير كافية','Insufficient data'),t('يتطلب النموذج 150 شمعة مكتملة على الأقل.','At least 150 closed candles are required.'),'spark')}<p class="muted small mt">${t('انحدار لوجستي على عوائد سابقة وRSI، مقسّم زمنيًا. الاحتمال غير معاير ولا يمثل ثقة ربح؛ لا يُفعّل تداولًا تلقائيًا.','Logistic regression on lagged returns and RSI, split chronologically. Probability is uncalibrated and is not a profit confidence score. It does not trigger automatic trades.')}</p></div></section></div><section class="panel below"><div class="panel-head"><h2>${t('مسار القرار','Decision process')}</h2></div><div class="panel-body flow">${[[t('بيانات حديثة','Fresh data'),t('فحص المصدر والوقت ودفتر الأوامر','Check source, timestamps and order books')],[t('تكلفة مكتملة','Full modeled cost'),t('عمق فعلي ورسوم السوق والانزلاق','Available depth, market fees and slippage')],[t('بوابة المخاطر','Risk gate'),t('الرصيد والحدود والخسارة اليومية','Balance, exposure and daily loss limits')],[t('محاكاة مسجلة','Recorded simulation'),t('زوج كامل أو مركز اتجاهي واضح','Complete set or explicit directional position')]].map(([title,body],i)=>`<div class="flow-step"><div class="step">0${i+1}</div><strong>${title}</strong><p>${body}</p></div>`).join('')}</div></section><section class="panel below"><div class="panel-head"><h2>${t('سجل قرارات البوت','Bot decision log')}</h2>${btn(icon('download')+t('تصدير','Export'),'exportEvents','compact')}</div>${wallet.events.length?wallet.events.slice(0,30).map(e=>`<div class="audit-row"><span class="audit-icon">${icon(e.key==='blocked'?'shield':'activity')}</span><div>${eventLabel(e.key)}${e.detail?`<small>${esc(e.key==='blocked'?reason(e.detail):e.detail)}</small>`:''}</div><span class="audit-time">${time(e.at)}</span></div>`).join(''):empty(t('السجل جاهز','Decision log is ready'),t('شغّل البوت التجريبي لتسجيل الفحص والقبول والرفض.','Start the paper bot to record scans, accepted entries and rejections.'),'book')}</section>`;}
function risk(){const fields=[['maxTrade',t('الحد الأقصى للصفقة ($)','Maximum trade ($)'),10,100000,1],['maxExposure',t('الانكشاف الكلي ($)','Total exposure ($)'),10,1000000,1],['dailyLoss',t('حد الخسارة المحققة يوميًا ($)','Daily realized loss cap ($)'),1,100000,1],['maxPositions',t('أقصى عدد للمراكز','Maximum positions'),1,50,1],['minEdge',t('أدنى عائد للزوج (%)','Minimum pair edge (%)'),0.01,20,.01],['slippageBps',t('الانزلاق المفترض (نقطة أساس)','Assumed slippage (bps)'),0,500,1],['spotFeeBps',t('رسوم التداول الفوري (نقطة أساس)','Assumed spot fee (bps)'),0,200,1],['stopLossPct',t('وقف خسارة البيتكوين (%)','Bitcoin stop loss (%)'),.1,50,.1],['takeProfitPct',t('جني ربح البيتكوين (%)','Bitcoin take profit (%)'),.1,100,.1]];return `${pageTitle(t('حدود واضحة. تحكّم كامل.','Clear limits. Full control.'),t('تُطبّق الحدود على كل دخول تجريبي، يدويًا أو آليًا.','Limits apply to every paper entry, manual or automated.'))}<div class="cols2"><section class="panel"><div class="panel-head"><h2>${icon('shield')}${t('حدود المحفظة','Portfolio limits')}</h2><span class="pill grey">${t('تجريبي','Paper')}</span></div><form id="riskForm" class="panel-body"><div class="form-grid">${fields.map(([k,label,min,max,step])=>`<div class="field"><label for="risk-${k}">${label}</label><input id="risk-${k}" name="${k}" type="number" value="${wallet.risk[k]}" min="${min}" max="${max}" step="${step}" required></div>`).join('')}</div><small class="muted">${t('اليوم يُحسب بتوقيت UTC. رسوم Polymarket تُقرأ من السوق؛ رسوم التداول الفوري افتراض تحليلي.','Daily limits reset at UTC midnight. Polymarket fees are market-specific; spot fees are modeling assumptions.')}</small><div class="form-actions"><button class="button primary">${t('حفظ الحدود','Save limits')}</button></div></form></section><div class="stack" style="align-content:start"><section class="panel"><div class="panel-head"><h2>${t('إيقاف الطوارئ','Emergency stop')}</h2>${status(!wallet.halted,t('التداول مسموح','Entries enabled'),t('الدخول متوقف','Entries halted'))}</div><div class="panel-body"><p class="muted">${t('يوقف البوت ويمنع دخول صفقات جديدة. إغلاق المراكز لتقليل المخاطر يظل متاحًا؛ المراكز المفتوحة لا تُغلق تلقائيًا بهذا الزر.','Stops the bot and blocks new entries. Risk-reducing exits remain available. This button does not liquidate open positions.')}</p><div class="form-actions">${btn(icon('stop')+(wallet.halted?t('رفع إيقاف الطوارئ','Release emergency stop'):t('تفعيل الإيقاف','Activate stop')),wallet.halted?'resumeLegacy':'halt',wallet.halted?'primary':'danger')}</div></div></section><section class="panel"><div class="panel-head"><h2>${t('بياناتك التجريبية','Your paper workspace')}</h2></div><div class="panel-body"><p class="muted">${t('يمكنك تصدير المحفظة واستعادتها على جهاز آخر. استيراد نسخة يستبدل المحفظة الحالية فقط.','Export your wallet and restore it on another device. Importing a backup replaces the current local wallet.')}</p><div class="action-grid">${btn(t('تنزيل نسخة','Download backup'),'exportWallet')}${btn(t('استيراد نسخة','Import backup'),'importWallet')}${btn(t('بدء محفظة جديدة','Reset paper wallet'),'resetWallet','danger')}</div><input type="file" id="importFile" accept="application/json,.json" hidden></div></section></div></div>`;}
function connectors(){const sources=[['Binance',t('شموع ودفتر أوامر BTC/USDT؛ قراءة عامة بلا مفاتيح.','BTC/USDT candles and order book; public read-only access.'),'https://github.com/binance/binance-spot-api-docs/blob/master/faqs/market_data_only.md'],['Polymarket',t('أسواق صعود وهبوط البيتكوين، دفتر الطرفين وجدول رسوم السوق.','Bitcoin UP/DOWN markets, both order books and per-market fee schedules.'),'https://docs.polymarket.com/trading/fees'],['OKX / Bybit',t('مقارنة أسعار BTC/USDT عند توفر المصدرين.','Compare BTC/USDT quotes when sources are available.'),'https://www.okx.com/docs-v5/en/']];const repos=[['Hummingbot','Apache-2.0',t('صناعة السوق والتحوط بين المنصات','Market making and cross-exchange hedging'),'hummingbot/hummingbot'],['Freqtrade / FreqAI','GPL-3.0',t('استراتيجيات العملات والتعلم الآلي','Crypto strategies and machine learning'),'freqtrade/freqtrade'],['Polymarket SDK','MIT',t('حزمة Polymarket الرسمية الموحدة','Official unified Polymarket SDK'),'Polymarket/py-sdk'],['NautilusTrader','LGPL-3.0',t('محرك اختبارات وتنفيذ قائم على الأحداث','Event-driven backtesting and execution'),'nautechsystems/nautilus_trader'],['CCXT','MIT',t('واجهات موحدة لبيانات المنصات','Unified exchange interfaces'),'ccxt/ccxt'],['LEAN','Apache-2.0',t('محرك أبحاث واختبارات متعدد الأصول','Multi-asset research and backtest engine'),'QuantConnect/Lean']];return `${pageTitle(t('المصادر والربط','Data & connections'),t('اعرف مصدر كل سعر، وما الذي يعمل فعليًا.','Know where every price comes from, and what is actually running.'))}${connectionPaths()}<div class="source-grid">${sources.map(([name,desc,url])=>{const ok=name==='Polymarket'?!!S.snapshot?.markets.some(m=>m.up.asks.length&&m.down.asks.length):name==='Binance'?!!S.snapshot?.exchanges.some(e=>e.id==='Binance'&&e.ok&&Date.now()-e.asOf<20000):!!S.snapshot?.exchanges.some(e=>e.id!=='Binance'&&e.ok);return `<section class="panel source-card"><div class="source-top"><span class="source-logo">${name[0]}</span>${status(ok)}</div><h2 class="mt">${name}</h2><p>${desc}</p><a href="${url}" target="_blank" rel="noopener">${t('المصدر الرسمي','Official documentation')} ↗</a></section>`}).join('')}</div><section class="panel below"><div class="panel-head"><h2>${t('التنفيذ الحقيقي','Real-money execution')}</h2><span class="pill amber">${t('غير متصل','Not connected')}</span></div><div class="panel-body"><p class="muted">${t('النسخة الحالية تعمل ببيانات عامة ومحفظة تجريبية محلية. لا توجد مفاتيح تداول أو محفظة بلوكشين متصلة، ولا تُرسل أوامر مالية. تفعيل حساب حقيقي يتطلب موصلًا خادميًا موثقًا واختبار تنفيذ وحدودًا مستقلة.','This version uses public data and a device-local paper wallet. No exchange credentials or blockchain wallet are connected, and no financial orders are sent. Live operation requires an authenticated server connector, execution validation, and independent risk limits.')}</p><div class="metric-row"><span>${t('وتيرة التحديث','Refresh cadence')}</span><span>${t('10 ثوانٍ أثناء فتح الصفحة','Every 10 seconds while open')}</span></div><div class="metric-row"><span>${t('التشغيل المستمر عالي السرعة','Continuous high-speed operation')}</span><span class="amber">${t('غير مفعّل','Not enabled')}</span></div></div></section><section class="panel below"><div class="panel-head"><h2>${t('مراجع التطوير المفتوحة','Open-source research references')}</h2><span class="pill grey">${t('مراجع، ليست خدمات متصلة','References, not connected engines')}</span></div><div class="panel-body"><p class="muted mb">${t('محرك هذه المنصة مكتوب خصيصًا لها. الروابط التالية لمشاريع دُرست أثناء التصميم؛ لم تُدمج خدماتها أو تُشغّل بوتاتها داخل الحساب.','This platform uses its own implementation. These projects informed the research; their services and bots are not integrated into this account.')}</p><div class="source-grid">${repos.map(([name,license,desc,path])=>`<div class="panel source-card"><div class="source-top"><h3>${name}</h3></div><p>${desc}</p><span class="pill grey num">${license}</span><br><a href="https://github.com/${path}" target="_blank" rel="noopener">GitHub ↗</a></div>`).join('')}</div></div></section>`;}
function eventLabel(k){const a={scan:['اكتمل مسح الفرص','Opportunity scan completed'],noEdge:['انتظار: لا فرصة تستوفي العائد والحدود','Wait: no candidate passes edge and risk limits'],opened:['فُتح مركز تجريبي','Paper position opened'],closed:['أُغلق مركز تجريبي','Paper position closed'],blocked:['رُفض الدخول','Entry rejected'],halt:['تغيّرت حالة إيقاف الطوارئ','Emergency stop changed'],risk:['حُدّثت حدود المخاطر','Risk limits updated'],autoStart:['بدأ البوت التجريبي','Paper bot started'],autoStop:['توقف البوت التجريبي','Paper bot stopped'],manual:['إغلاق يدوي','Manual exit'],stop:['وقف خسارة','Stop loss'],take:['جني ربح','Take profit'],maturity:['تسوية زوج افتراضية','Modeled pair settlement'],import:['استُعيدت نسخة المحفظة','Wallet backup restored']};return a[k]?t(...a[k]):esc(k);}
function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=t('منصة فرص التداول','Trading Opportunities Platform');const labs=labels(),icons=['radar','scan','shield','activity','grid','scan','chart','wallet','spark','shield','plug'];$('#app').innerHTML=`<div class="shell"><aside class="sidebar ${S.mobile?'open':''}"><a class="brand" href="#stp" data-page="stp"><span class="brand-icon">F</span><div><div class="brand-word"><span>فرص التداول</span></div><small>${t('منصة موحدة لاقتناص الفرص','Unified opportunity platform')}</small></div></a><div class="nav-caption">${t('مساحة العمل','WORKSPACE')}</div><nav class="nav" aria-label="${t('القائمة الرئيسية','Main navigation')}">${Object.entries(labs).map(([k,l],i)=>`<button data-page="${k}" class="${S.page===k?'active':''}" ${S.page===k?'aria-current="page"':''}>${icon(icons[i])}<span>${l}</span>${k==='portfolio'&&wallet.positions.length?`<span class="count">${wallet.positions.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="workspace-card">${status(true,t('متابعة السوق + محاكاة','LIVE DATA + PAPER TRADING'))}<p>${t('أسعار فعلية من المنصات. التداول بأموال افتراضية في قسم المحفظة.','Actual exchange prices. Virtual trading stays in the paper portfolio.')}</p></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><button class="mobile-toggle" data-action="menu" aria-label="${t('فتح القائمة','Open menu')}">${icon('menu')}</button><span>${t('مساحة التداول','Trading workspace')}</span><span>/</span><b>${labs[S.page]}</b></div><div class="top-actions"><span id="liveConnection">${status(S.page==='markets'?!!S.marketData?.observations.some(r=>liveState(r,S)==='fresh'):!!freshBook(),t('بيانات سوق متصلة','Market data connected'),S.loading?t('جارٍ الاتصال','Connecting'):t('تحقق من المصادر','Check data sources'))}</span><button class="button compact" data-action="language" aria-label="${lang==='ar'?'Switch to English':'التبديل إلى العربية'}">${lang==='ar'?'EN':'عربي'}</button>${btn(icon('stop')+(wallet.halted?t('متوقف','Halted'):t('إيقاف طارئ','Emergency stop')),'halt','danger compact')}<span class="avatar">FB</span></div></header><div class="content">${S.error?notice(t('تعذر تحديث البيانات. تظهر آخر قراءة بوقتها؛ الدخول بأسعار قديمة ممنوع.','Market refresh failed. Any last values retain their timestamps; stale entries are blocked.'),true):''}${({stp:stpPage,signals:desk.radar,execution:desk.execution,markets,dashboard,opportunities,lab,portfolio,intelligence,risk,connectors})[S.page]()}<footer class="footer"><span>© 2026 منصة فرص التداول · ${t('تحليل أدق. قرار أوضح.','Sharper analysis. Clearer decisions.')}</span><span>${t('آخر مسح · توقيت الكويت','Last scan · Kuwait time')}: <span class="num">${time(S.page==='markets'?S.marketData?.generatedAt:S.snapshot?.generatedAt)}</span> · ${S.page==='markets'?t('بيانات سوق فعلية','Actual market observations'):t('تداول تجريبي','Paper trading')}</span></footer></div></main></div>`;updateLiveFreshness(S,t);}
function showDialog(content){$('#dialog').innerHTML=`<div class="dialog-content"><button class="close" data-action="closeDialog" aria-label="${t('إغلاق','Close')}">×</button>${content}</div>`;if(!$('#dialog').open)$('#dialog').showModal();}
function inspect(id){const m=S.snapshot?.markets.find(x=>x.id===id);if(!m)return;const q=pairQuote(m,S.qty,wallet.risk.slippageBps),error=q.ok?riskCheck(wallet,q.total):q.reason;const can=q.ok&&q.edgePct>=wallet.risk.minEdge&&!error&&!wallet.positions.some(p=>p.marketId===m.id);const rows=q.ok?[[t('عدد الأزواج','Pair shares'),n(q.qty,0)],[t('تكلفة صعود + هبوط','UP + DOWN cost'),money(q.up.gross+q.down.gross,4)],[t('رسوم الطرفين','Both taker fees'),money(q.fees,4)],[t('إجمالي الدخول النموذجي','Modeled entry cost'),money(q.total,4)],[t('قيمة زوج كامل عند التسوية','Complete-set settlement value'),money(q.payout,4)],[t('صافي العائد النموذجي','Modeled net edge'),money(q.net,4)+' / '+pct(q.edgePct)]]:[];
  showDialog(`<span class="pill grey num">BTC · ${m.frame}</span><h2 class="mt">${t('فحص الزوج قبل المحاكاة','Inspect before simulating')}</h2><p class="muted small">${esc(m.title)}</p><div class="mt">${rows.map(([k,v])=>`<div class="metric-row"><span>${k}</span><span class="num">${v}</span></div>`).join('')}</div>${!q.ok?notice(reason(q.reason),true):''}${notice(t('المحاكاة تفترض تعبئة الطرفين معًا وتسوية كل زوج بدولار. التنفيذ الحقيقي قد يملأ طرفًا واحدًا؛ الربح ليس مضمونًا، ورسوم الشبكة غير محسوبة.','Simulation assumes both legs fill together and each complete set settles for $1. Actual orders may fill only one leg; profits are not guaranteed and network costs are excluded.'),true)}${error&&q.ok?`<p class="error-text">${reason(error)}</p>`:''}<div class="form-actions"><a class="button" href="https://polymarket.com/event/${encodeURIComponent(m.slug)}" target="_blank" rel="noopener">${t('السوق الأصلي','Original market')} ↗</a>${btn(t('محاكاة شراء الزوج','Simulate pair purchase'),'buyPair','primary',`data-id="${m.id}" ${can?'':'disabled'}`)}</div>`);
}
async function mutate(fn){const run=async()=>{try{const stored=JSON.parse(localStorage.getItem(KEY));if(stored?.version===2)wallet=stored;}catch{}wallet.auto=false;const result=await fn();save();return result;};return navigator.locks? navigator.locks.request(KEY,run):run();}
async function buyPair(id,automatic=false){return mutate(()=>{const m=S.snapshot?.markets.find(x=>x.id===id),q=pairQuote(m,S.qty,wallet.risk.slippageBps);if(!q.ok)throw Error(q.reason);if(q.edgePct<wallet.risk.minEdge)throw Error('noEdge');if(wallet.positions.some(p=>p.marketId===id))throw Error('duplicate');const p=openPaper(wallet,{kind:'pair',marketId:m.id,conditionId:m.conditionId,frame:m.frame,qty:q.qty,cost:q.total,payout:q.payout,fees:q.fees,endAt:Date.parse(m.endDate),entryQuoteAt:Math.min(m.up.asOf,m.down.asOf),assumption:'both-legs-filled-and-complete-set-payout',automatic});log('opened',`Polymarket ${m.frame} · ${n(p.qty,0)} · ${money(p.cost)}`);});}
async function buySpot(budget){return mutate(()=>{const b=freshBook();if(!b)throw Error('stale');if(!Number.isFinite(budget)||budget<10)throw Error('invalidAmount');const riskError=riskCheck(wallet,budget);if(riskError)throw Error(riskError);const unit=b.asks[0].price*(1+wallet.risk.slippageBps/10000)*(1+wallet.risk.spotFeeBps/10000);let qty=budget/unit;let q=fillBook(b.asks,qty,'buy',wallet.risk.slippageBps,wallet.risk.spotFeeBps);if(!q)throw Error('depth');if(q.total>budget){qty*=budget/q.total*.999999;q=fillBook(b.asks,qty,'buy',wallet.risk.slippageBps,wallet.risk.spotFeeBps);}if(!q||q.total>budget+1e-6)throw Error('depth');const p=openPaper(wallet,{kind:'spot',qty,cost:q.total,entry:q.vwap,fees:q.fees,stopLossPct:wallet.risk.stopLossPct,takeProfitPct:wallet.risk.takeProfitPct,entryQuoteAt:b.asOf});log('opened',`BTC/USDT · ${n(qty,6)} · ${money(p.cost)}`);});}
async function closeSpot(id,why='manual'){return mutate(()=>{const p=wallet.positions.find(x=>x.id===id);if(!p||p.kind!=='spot')throw Error('invalidAmount');const b=freshBook();if(!b)throw Error('stale');const q=fillBook(b.bids,p.qty,'sell',wallet.risk.slippageBps,wallet.risk.spotFeeBps);if(!q)throw Error('depth');const trade=closePaper(wallet,id,q.total,Date.now(),why);log('closed',`BTC/USDT · ${money(trade.pnl)}`);});}
async function processPositions(){await mutate(()=>{for(const p of [...wallet.positions]){if(p.kind==='pair'&&Date.now()>=p.endAt){closePaper(wallet,p.id,p.payout,Date.now(),'maturity');log('maturity',`${p.frame} · ${money(p.payout-p.cost)}`);}else if(p.kind==='spot'){const b=freshBook();if(!b)continue;const q=fillBook(b.bids,p.qty,'sell',wallet.risk.slippageBps,wallet.risk.spotFeeBps);if(!q)continue;const ret=(q.total/p.cost-1)*100;const why=ret<=-p.stopLossPct?'stop':ret>=p.takeProfitPct?'take':null;if(why){closePaper(wallet,p.id,q.total,Date.now(),why);log('closed',`BTC/USDT · ${why} · ${money(q.total-p.cost)}`);}}}});}
async function runBot(){if(!S.auto||S.busy)return;S.busy=true;try{if(wallet.halted){S.auto=false;return;}const all=candidates(),eligible=all.find(({m,q})=>q.ok&&q.edgePct>=wallet.risk.minEdge&&!wallet.positions.some(p=>p.marketId===m.id));if(eligible){await buyPair(eligible.m.id,true);}else if(Date.now()-(S.lastWait||0)>60000){await mutate(()=>log('noEdge'));S.lastWait=Date.now();}}catch(e){await mutate(()=>log('blocked',e.message));if(e.message==='dailyLoss'||e.message==='halted')S.auto=false;}finally{S.busy=false;}}
async function fetchHistory(){try{const interval=S.interval;const r=await fetch(`/api/candles?interval=${interval}`,{signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error();const data=await r.json();if(interval!==S.interval)return;S.candles=data.data;S.historySource=data.source;S.model=analyze(S.candles);}catch{S.candles=[];S.model=null;}}
function mayRender(){return !['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)&&!['risk','lab','execution'].includes(S.page)&&!(S.page==='opportunities'&&S.scanner==='maker');}
async function refresh(manual=false){if(S.refreshing)return;S.refreshing=true;try{const tasks=[fetch('/api/snapshot',{signal:AbortSignal.timeout(26000)}).then(async r=>{if(!r.ok)throw Error();S.snapshot=await r.json();S.error=false;})];if(manual||!S.candles.length||Date.now()-(S.historyAt||0)>60000){tasks.push(fetchHistory());S.historyAt=Date.now();}await Promise.all(tasks);await processPositions();await runBot();}catch{S.error=true;}finally{S.refreshing=false;S.loading=false;if(manual||mayRender())render();}}
function exportJSON(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`fainance-${name}-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const riskRanges={maxTrade:[10,100000],maxExposure:[10,1000000],dailyLoss:[1,100000],maxPositions:[1,50],minEdge:[.01,20],slippageBps:[0,500],spotFeeBps:[0,200],stopLossPct:[.1,50],takeProfitPct:[.1,100]};
function validateRisk(r){return Object.entries(riskRanges).every(([k,[min,max]])=>Number.isFinite(r[k])&&r[k]>=min&&r[k]<=max)&&(Number.isInteger(r.maxPositions))&&r.maxTrade<=r.maxExposure;}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;try{
  if(el.dataset.page){e.preventDefault();S.page=el.dataset.page;S.mobile=false;history.replaceState(null,'',`#${S.page}`);render();window.scrollTo(0,0);if(S.page==='stp')loadSTP();if(S.page==='markets')refreshMarketData();if(['signals','execution'].includes(S.page))desk.refresh();return;}
  if(el.dataset.interval){S.interval=el.dataset.interval;S.candles=[];S.model=null;S.result=null;render();await fetchHistory();render();return;}
  if(el.dataset.frame){S.frame=el.dataset.frame;render();return;}if(el.dataset.scanner){S.scanner=el.dataset.scanner;render();return;}if(el.dataset.strategy){S.strategy=el.dataset.strategy;S.result=null;render();return;}
  const a=el.dataset.action;if(!a)return;
  if(a==='stpRefresh')await loadSTP();
  if(a==='language'){lang=lang==='ar'?'en':'ar';localStorage.setItem('fainance.language',lang);render();}
  if(a==='menu'){S.mobile=!S.mobile;render();}
  if(a==='refresh')await refresh(true);
  if(a==='refreshMarkets')await Promise.all([refreshMarketData(true),refresh()]);
  if(a==='exportMarketData'&&S.marketData)exportJSON('market-readings',{...S.marketData,observations:S.marketData.observations.map(r=>({...r,state:liveState(r,S)})),exportedAt:new Date().toISOString(),displayTimezone:'Asia/Kuwait'});
  if(a==='closeDialog')$('#dialog').close();
  if(a==='inspect')inspect(el.dataset.id);
  if(a==='halt'){await desk.stop();await mutate(()=>{wallet.halted=true;S.auto=false;log('halt');});render();toast(t('توقف المحركان. المراكز الحالية لم تُبع.','Both engines stopped. Existing holdings were retained.'));}
  if(a==='resumeLegacy'){await mutate(()=>{wallet.halted=false;S.auto=false;log('halt');});render();toast(t('رُفع إيقاف المحفظة فقط؛ البوت ما زال متوقفًا.','Portfolio stop released; automatic bot remains off.'));}
  if(a==='auto'){if(wallet.halted)throw Error('halted');S.auto=!S.auto;await mutate(()=>log(S.auto?'autoStart':'autoStop'));render();if(S.auto)await runBot();}
  if(a==='buyPair'){el.disabled=true;await buyPair(el.dataset.id);$('#dialog').close();render();toast(t('سُجّل الزوج في المحفظة التجريبية.','Pair recorded in your paper portfolio.'));}
  if(a==='closeSpot'){el.disabled=true;await closeSpot(el.dataset.id);render();toast(t('أُغلق المركز التجريبي.','Paper position closed.'));}
  if(a==='exportWallet')exportJSON('wallet',{...wallet,auto:false});
  if(a==='exportEvents')exportJSON('decisions',wallet.events);
  if(a==='exportBacktest'&&S.result)exportJSON('backtest',{...S.result,strategy:S.strategy,interval:S.interval,source:S.historySource,mode:'historical simulation'});
  if(a==='importWallet')$('#importFile').click();
  if(a==='resetWallet')showDialog(`<h2>${t('بدء محفظة تجريبية جديدة؟','Start a new paper wallet?')}</h2><p class="muted">${t('سيُحذف سجل المحاكاة المحلي وتبدأ برصيد افتراضي 10,000 دولار. صدّر نسختك أولًا إن أردت الاحتفاظ بها.','This clears your local simulation history and starts with $10,000 virtual cash. Export a backup first if needed.')}</p><div class="form-actions">${btn(t('إلغاء','Cancel'),'closeDialog')}${btn(t('تأكيد بدء محفظة جديدة','Confirm reset'),'confirmReset','danger')}</div>`);
  if(a==='confirmReset'){await mutate(()=>{wallet=newWallet();S.auto=false;});$('#dialog').close();render();}
  if(a==='confirmImport'&&S.imported){await mutate(()=>{wallet=S.imported;wallet.halted=true;wallet.auto=false;S.auto=false;log('import');});S.imported=null;$('#dialog').close();render();toast(t('استُعيدت المحفظة مع تفعيل إيقاف الطوارئ.','Wallet restored with emergency stop active.'));}
}catch(error){toast(reason(error.message));if(el.dataset.action==='buyPair'||el.dataset.action==='closeSpot')el.disabled=false;}});
document.addEventListener('change',async e=>{if(e.target.id==='scanQty'){const x=Number(e.target.value);if(x>=5&&x<=10000){S.qty=x;render();}}if(e.target.id==='positiveOnly'){S.positiveOnly=e.target.checked;render();}if(e.target.id==='importFile'){try{const file=e.target.files[0];if(!file)return;if(file.size>3e6)throw Error();const w=JSON.parse(await file.text());if(w.version!==2||!Number.isFinite(w.cash)||w.cash<0||!Number.isFinite(w.initial)||w.initial<=0||!Array.isArray(w.positions)||w.positions.length>50||!Array.isArray(w.trades)||w.trades.length>10000||!Array.isArray(w.events)||!validateRisk(w.risk))throw Error();for(const p of [...w.positions,...w.trades]){if(!['spot','pair'].includes(p.kind)||typeof p.id!=='string'||!Number.isFinite(p.qty)||p.qty<=0||!Number.isFinite(p.cost)||p.cost<=0||!Number.isFinite(p.openedAt))throw Error();if(p.kind==='spot'&&(!Number.isFinite(p.entry)||p.entry<=0||!Number.isFinite(p.stopLossPct)||!Number.isFinite(p.takeProfitPct)))throw Error();if(p.kind==='pair'&&(!Number.isFinite(p.endAt)||!Number.isFinite(p.payout)||p.payout!==p.qty))throw Error();}if(new Set(w.positions.map(p=>p.id)).size!==w.positions.length||w.trades.some(p=>!Number.isFinite(p.pnl)||!Number.isFinite(p.closedAt)||!Number.isFinite(p.proceeds)))throw Error();w.events=w.events.filter(x=>x&&typeof x.key==='string'&&Number.isFinite(x.at)).slice(0,1000);S.imported=w;showDialog(`<h2>${t('استعادة المحفظة؟','Restore wallet backup?')}</h2><p class="muted">${t('سيحل هذا السجل محل المحفظة الحالية على الجهاز.','This ledger will replace your current local wallet.')}</p><div class="metric-row"><span>${t('السيولة','Cash')}</span><span class="num">${money(w.cash)}</span></div><div class="form-actions">${btn(t('إلغاء','Cancel'),'closeDialog')}${btn(t('استبدال واستعادة','Replace and restore'),'confirmImport','primary')}</div>`);}catch{toast(t('ملف المحفظة غير صالح أو غير متوافق.','Invalid or incompatible wallet backup.'));}}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f));try{
  if(f.id==='riskForm'){const r=Object.fromEntries(Object.entries(data).map(([k,v])=>[k,Number(v)]));if(!validateRisk(r)){toast(t('راجع الحدود: حد الصفقة يجب ألا يتجاوز الانكشاف الكلي.','Check limits: trade size cannot exceed total exposure.'));return;}await mutate(()=>{wallet.risk=r;log('risk');});toast(t('حُفظت حدود المخاطر.','Risk limits saved.'));render();}
  if(f.id==='spotForm'){const b=f.querySelector('button');b.disabled=true;try{await buySpot(Number(data.budget));toast(t('سُجّل شراء تجريبي بالأسعار الحالية.','Paper buy recorded at current quotes.'));render();}finally{b.disabled=false;}}
  if(f.id==='backtestForm'){S.result=backtest(S.candles,{capital:Number(data.capital),feeBps:Number(data.feeBps),slippageBps:Number(data.slippageBps),strategy:S.strategy});render();toast(t('اكتمل الاختبار التاريخي.','Backtest complete.'));}
  if(f.id==='makerForm'){const b=freshBook();if(!b)throw Error('stale');const q=makerQuote(b.price,Number(data.spread),Number(data.inventory));if(!q)throw Error('invalidAmount');const crossing=q.bid>=b.asks[0].price||q.ask<=b.bids[0].price;$('#makerResult').innerHTML=`<div class="summary-result"><div class="metric-row"><span>${t('شراء مقترح','Proposed bid')}</span><span class="num positive">${money(q.bid)}</span></div><div class="metric-row"><span>${t('بيع مقترح','Proposed ask')}</span><span class="num negative">${money(q.ask)}</span></div><p class="small muted">${crossing?t('انحياز المخزون يجعل العرض يعبر السوق؛ يُرفض كأمر صانع سوق.','Inventory skew crosses the market; reject as a post-only quote.'):t('عرض نظري فقط. التنفيذ يعتمد على طابور الأوامر والمخزون.','Quotes only. Fills depend on queue position and inventory.')}</p></div>`;}
  if(f.id==='hedgeForm'){const up=Number(data.up),down=Number(data.down);if(!Number.isFinite(up)||!Number.isFinite(down)||up<0||down<0)throw Error('invalidAmount');const paired=Math.min(up,down),residual=Math.abs(up-down),coverage=up+down?2*paired/(up+down)*100:0;$('#hedgeResult').innerHTML=`<div class="summary-result"><div class="metric-row"><span>${t('أزواج مكتملة','Complete sets')}</span><span class="num">${n(paired,0)}</span></div><div class="metric-row"><span>${t('أسهم مكشوفة للاتجاه','Unhedged shares')}</span><span class="num amber">${n(residual,0)}</span></div><div class="metric-row"><span>${t('تغطية مجموع الأسهم','Share coverage')}</span><span class="num green">${n(coverage,1)}%</span></div><p class="muted small">${t('صالح فقط لطرفي نفس السوق. لا يحدد الربح دون معرفة أسعار الشراء والرسوم.','Valid only for opposite outcomes of the same market. P&L also requires entry prices and fees.')}</p></div>`;}
}catch(error){toast(reason(error.message));}});
window.addEventListener('storage',e=>{if(e.key===KEY){try{const w=JSON.parse(e.newValue);if(w?.version===2){wallet=w;if(wallet.halted)S.auto=false;if(mayRender())render();}}catch{}}});
document.addEventListener('click',e=>{if(S.mobile&&!e.target.closest('.sidebar')&&!e.target.closest('[data-action="menu"]')){S.mobile=false;$('.sidebar')?.classList.remove('open');}});
window.addEventListener('online',()=>refresh());
let STP={loading:false,result:null,error:null};
async function loadSTP(){STP.loading=true;try{const r=await fetch('/api/stp/opportunities?interval=1h',{cache:'no-store',signal:AbortSignal.timeout(20000)});const x=await r.json();if(!r.ok)throw Error(x.error||'Unavailable');STP.result=x;STP.error=null;}catch(e){STP.error=e.message;}finally{STP.loading=false;if(S.page==='stp')render();}}
function stpPage(){const x=STP.result,o=x?.opportunities?.[0],m=o?.metrics||{},l=o?.levels;return `${pageTitle(t('مسار سعد للتداول','Saad Trading Path'),t('رادار الفرص المعتمد على الشموع المكتملة — وضع مراقبة فقط','Completed-bar opportunity radar — read-only'),btn(t('تحديث الفحص','Refresh scan'),'stpRefresh'))}<div class="card"><h3>${t('حالة المحرك','Engine status')}</h3><p>${STP.loading?t('جارٍ الفحص','Scanning'):STP.error?esc(STP.error):o?esc(o.status):t('لم يبدأ الفحص','Scan not started')}</p><p class="muted">${t('التغطية الحالية: BTC/USDT فقط. لا توجد بيانات أمريكية أو كويتية متصلة بهذا المسار بعد.','Current coverage: BTC/USDT only. US and Kuwait feeds are not yet connected.')}</p>${o?`<div class="metric-row"><span>${esc(o.symbol)}</span><strong>${esc(o.status)}</strong></div><div class="metric-row"><span>RSI 14</span><strong>${n(m.rsi14)}</strong></div><div class="metric-row"><span>RVOL 20</span><strong>${n(m.rvol20)}</strong></div><div class="metric-row"><span>EMA 20 / 50 / 200</span><strong>${n(m.ema20)} / ${n(m.ema50)} / ${n(m.ema200)}</strong></div>${l?`<div class="metric-row"><span>Entry / SL / TP1 / TP2 / TP3</span><strong>${[l.entry,l.stopLoss,l.tp1,l.tp2,l.tp3].map(v=>n(v)).join(' / ')}</strong></div>`:''}<p class="muted">${(o.reasons||[]).map(esc).join(' · ')}</p>`:''}<p class="muted">${t('الإشارات تعليمية/بحثية وليست أوامر تداول.','Research signals are not trade orders.')}</p></div>`;}
const desk=createTradingDesk({t,n,time,esc,icon,btn,notice,empty,pageTitle,toast,render,exportJSON});
const initial=location.hash.slice(1);if(labels()[initial])S.page=initial;
render();refresh();refreshMarketData();desk.refresh();if(S.page==='stp')loadSTP();setInterval(()=>{if(!document.hidden)refresh();},10000);setInterval(()=>{if(!document.hidden&&S.page==='markets')refreshMarketData();},5000);setInterval(()=>{if(!document.hidden)updateLiveFreshness(S,t);},1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateLiveFreshness(S,t);if(S.page==='markets')refreshMarketData();}});

function connectionPaths(){return `<section class="panel mb"><div class="panel-head"><h2>${t('مسارات مشروعك','Your project connections')}</h2></div><div class="panel-body"><div class="metric-row"><span>GitHub</span><a class="inline-link" href="https://github.com/Q8-ux/saad/tree/nexus-markets-production/nexus-deploy" target="_blank" rel="noopener">${t('كود المنصة وسجل التحديثات','Platform source and change history')} ↗</a></div><div class="metric-row"><span>Render</span><a class="inline-link" href="https://nexus-markets.onrender.com">${t('المنصة على رابطك الحالي','Platform on your existing URL')} ↗</a></div><div class="metric-row"><span>Supabase</span><span class="pill grey">${t('لا توجد قاعدة مرتبطة بالمنصة','No database connected to this app')}</span></div><p class="muted small mt">${t('المحفظة الآن محلية مع تصدير واستيراد. المزامنة بين الأجهزة تحتاج قاعدة خاصة بهذه المنصة وتسجيل دخول.','Your wallet is local with export/import. Cross-device synchronization requires a dedicated database and authentication for this platform.')}</p></div></section>`;}

function markets(){return liveMarkets({S,t,n,pct,sign,time,chart,icon,btn,notice,empty,marketTable,btcIcon});}
async function refreshMarketData(manual=false){
  if(S.marketRefreshing)return;S.marketRefreshing=true;
  try{const response=await fetch('/api/market-board',{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error();const data=await response.json();if(!Array.isArray(data.observations)||!Number.isFinite(data.generatedAt))throw Error();S.marketData=data;S.marketClock={server:Number.isFinite(data.serverNow)?data.serverNow:data.generatedAt,local:performance.now()};S.marketFetchFailed=false;}
  catch{S.marketFetchFailed=true;}
  finally{S.marketRefreshing=false;S.marketLoading=false;if(S.page==='markets'&&(manual||mayRender()))render();updateLiveFreshness(S,t);}
}
